/**
 * Compile-time contract check (BE-22): every response below, as the server declares it in docs/api/openapi.json (src/api/schema.d.ts,
 * generated by `npm run gen:api`), must fit the type the screens read. If the server renames a field, changes its type or makes it
 * nullable, `tsc` fails here instead of a screen failing at run time. Regenerate after the server's contract test updates the JSON.
 */
import type { Inbox } from "../features/notifications/NotificationBell";
import type { Cycle, Form, FormItem, FormRow, ImportPreview, IndicatorResults } from "./collection";
import type { components } from "./schema";
import type { Progress, Review, Scorecard } from "./scorecard";
import type { EmailDomain, IpAllowlist } from "./security";
import type {
  CollegeChart, ConflictList, Distribution, Home, IndicatorDetail, IndicatorRow, IndicatorTargets, InitiativeActivity, PlanPeriod, OrgUnit, StrategyTree, UnitIndicators,
} from "./tier1";
import type { Catalog, Effective, LogPage, LogsStatus, Me, RbacChange, RoleDetail, RoleSummary, UserDetail, UserListItem } from "./types";

type S = components["schemas"];

/**
 * The paths where what the server sends cannot be read as the web's type, or never. One allowance: where the server declares a
 * plain string, the web may name the values it knows (a tone, a state, a scope); a server enum with a value the web lacks still fails.
 */
type DeepDiff<Srv, Web, P extends string = ""> =
  [Srv] extends [Web] ? never
  : null extends Srv ? (null extends Web ? DeepDiff<Exclude<Srv, null>, Exclude<Web, null>, P> : P)
  : [Srv] extends [string] ? ([Web] extends [string] ? (string extends Srv ? never : P) : P)
  : [Srv] extends [readonly (infer SE)[]] ? ([Web] extends [readonly (infer WE)[]] ? DeepDiff<SE, WE, `${P}[]`> : P)
  : [Srv] extends [object] ? ([Web] extends [object]
    ? { [K in keyof Web & string]-?: K extends keyof Srv ? DeepDiff<Srv[K], Web[K], `${P}.${K}`> : `${P}.${K} (not sent)` }[keyof Web & string]
    : P)
  : P;
/** true when every field the web reads fits; otherwise the error names the paths that do not. */
type Fits<Server, Web> = [DeepDiff<Server, Web>] extends [never] ? true : { mismatch: DeepDiff<Server, Web> };
type Check<T extends true> = T;

export type ContractChecks = [
  Check<Fits<S["EmailDomainDto"], EmailDomain>>,
  Check<Fits<S["IpAllowlistDto"], IpAllowlist>>,
  Check<Fits<S["CycleDto"], Cycle>>,
  Check<Fits<S["ActivityDto"], InitiativeActivity>>,
  Check<Fits<S["PlanPeriodDto"], PlanPeriod>>,
  Check<Fits<S["FormRow"], FormRow>>,
  Check<Fits<S["FormDto"], Form>>,
  Check<Fits<S["FormItem"], FormItem>>,
  Check<Fits<S["ImportPreview"], ImportPreview>>,
  Check<Fits<S["IndicatorResultsDto"], IndicatorResults>>,
  Check<Fits<S["StrategyTreeDto"], StrategyTree>>,
  Check<Fits<S["OrgUnitDto"], OrgUnit>>,
  Check<Fits<S["HomeDto"], Home>>,
  Check<Fits<S["IndicatorRowDto"], IndicatorRow>>,
  Check<Fits<S["IndicatorDetailDto"], IndicatorDetail>>,
  Check<Fits<S["IndicatorTargetsDto"], IndicatorTargets>>,
  Check<Fits<S["ConflictListDto"], ConflictList>>,
  Check<Fits<S["CollegeChartDto"], CollegeChart>>,
  Check<Fits<S["UnitIndicatorsDto"], UnitIndicators>>,
  Check<Fits<S["DistributionDto"], Distribution>>,
  Check<Fits<S["ScorecardDto"], Scorecard>>,
  Check<Fits<S["ReviewDto"], Review>>,
  Check<Fits<S["ProgressDto"], Progress>>,
  Check<Fits<S["CatalogDto"], Catalog>>,
  Check<Fits<S["EffectiveDto"], Effective>>,
  Check<Fits<S["MeDto"], Me>>,
  Check<Fits<S["RoleSummaryDto"], RoleSummary>>,
  Check<Fits<S["RoleDetailDto"], RoleDetail>>,
  Check<Fits<S["RbacChangeDto"], RbacChange>>,
  Check<Fits<S["UserListItemDto"], UserListItem>>,
  Check<Fits<S["UserDetailDto"], UserDetail>>,
  Check<Fits<S["LogPageDto"], LogPage>>,
  Check<Fits<S["LogsStatusDto"], LogsStatus>>,
  Check<Fits<S["InboxDto"], Inbox>>,
];
